```css
:root {
  --ink: #e8f0f7;
  --ink-dim: #8ca3b8;
  --ink-faint: #5d7387;
  --deep: #070d15;
  --panel: #0e1722;
  --panel-2: #131f2c;
  --line: #1e2f40;
  --accent: #4fd1c5;
  --accent-dim: #2b8a83;
  --gold: #f0b429;
  --rose: #f26d6d;
  --green: #5fd08a;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  background: var(--deep);
  color: var(--ink);
  font: 14px/1.5 ui-sans-serif, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

h1, h2, h3 { margin: 0; font-weight: 650; letter-spacing: -0.01em; }

/* The top bar: the name of the tool and the three views it has. */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 16px 28px;
  background: linear-gradient(180deg, #0c1520, #080e16);
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: 0;
  z-index: 5;
}

.brand { display: flex; align-items: center; gap: 14px; }

.mark {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 2px solid var(--accent-dim);
  position: relative;
  flex: none;
}

.mark::after {
  content: "";
  position: absolute;
  inset: 8px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 14px var(--accent);
}

.brand h1 { font-size: 19px; }

.tagline { margin: 2px 0 0; color: var(--ink-dim); font-size: 12.5px; }

.tabs { display: flex; gap: 6px; }

.tab {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--ink-dim);
  padding: 7px 14px;
  border-radius: 7px;
  font: inherit;
  font-size: 13px;
  cursor: pointer;
}

.tab:hover { color: var(--ink); border-color: var(--accent-dim); }

.tab.is-active {
  color: var(--deep);
  background: var(--accent);
  border-color: var(--accent);
  font-weight: 600;
}

main { padding: 22px 28px 60px; }

.panel { max-width: 1240px; margin: 0 auto; }

/* The controls: a search box, two filters and the sort, in one row. */
.controls {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 14px;
  padding: 14px 16px;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 10px;
  margin-bottom: 16px;
}

.controls label { display: flex; flex-direction: column; gap: 5px; font-size: 11.5px; color: var(--ink-dim); }

.controls .search { flex: 1 1 240px; }

.controls .toggle { flex-direction: row; align-items: center; gap: 8px; }

input[type="search"], select {
  background: var(--panel-2);
  border: 1px solid var(--line);
  color: var(--ink);
  border-radius: 7px;
  padding: 8px 10px;
  font: inherit;
  font-size: 13px;
  min-width: 150px;
}

input[type="search"] { width: 100%; }

input[type="search"]:focus, select:focus { outline: none; border-color: var(--accent-dim); }

input[type="checkbox"] { accent-color: var(--accent); width: 15px; height: 15px; }

.count { margin: 0 0 0 auto; color: var(--ink-faint); font-size: 12.5px; }

.table-wrap {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 10px;
  overflow: hidden;
}

table { width: 100%; border-collapse: collapse; }

thead th {
  text-align: left;
  font-size: 11px;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--ink-faint);
  font-weight: 600;
  padding: 11px 14px;
  border-bottom: 1px solid var(--line);
  background: var(--panel-2);
}

tbody td { padding: 10px 14px; border-bottom: 1px solid rgba(30, 47, 64, 0.55); }

tbody tr:hover { background: rgba(79, 209, 197, 0.06); cursor: pointer; }

tbody tr:last-child td { border-bottom: none; }

.col-num, td.num { text-align: right; font-variant-numeric: tabular-nums; }

.col-rank { width: 46px; }

.rank { color: var(--ink-faint); font-variant-numeric: tabular-nums; }

.name-cell { display: flex; align-items: center; gap: 9px; }

.name-cell strong { font-weight: 600; }

.dot { width: 7px; height: 7px; border-radius: 50%; background: var(--accent-dim); flex: none; }

.dot.watch { background: var(--gold); box-shadow: 0 0 8px rgba(240, 180, 41, 0.6); }

.pill {
  font-size: 11px;
  color: var(--ink-dim);
  border: 1px solid var(--line);
  border-radius: 20px;
  padding: 2px 9px;
  white-space: nowrap;
}

.up { color: var(--green); }

.down { color: var(--rose); }

.value { color: var(--gold); font-weight: 600; }

.odds-cell { display: flex; align-items: center; gap: 8px; justify-content: flex-end; }

.bar { width: 52px; height: 5px; border-radius: 3px; background: var(--line); overflow: hidden; }

.bar > i { display: block; height: 100%; background: var(--accent); }

.note { color: var(--ink-dim); font-size: 13px; max-width: 760px; }

/* The model page: the formula, then what each term means. */
.lead { color: var(--ink-dim); max-width: 760px; }

.formula {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  background: var(--panel);
  border: 1px solid var(--line);
  border-left: 3px solid var(--accent);
  border-radius: 8px;
  padding: 14px 16px;
  color: var(--accent);
  font-size: 13.5px;
}

.model { display: grid; grid-template-columns: 180px 1fr; gap: 8px 18px; margin: 20px 0 26px; }

.model dt { color: var(--ink-dim); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 13px; }

.model dd { margin: 0; color: var(--ink); }

.terms { color: var(--ink-dim); max-width: 820px; padding-left: 20px; }

.terms li { margin-bottom: 10px; }

.terms strong { color: var(--ink); }

/* The detail view: a panel that slides in from the right. */
.detail {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: min(460px, 92vw);
  background: var(--panel);
  border-left: 1px solid var(--line);
  padding: 26px 26px 40px;
  overflow-y: auto;
  z-index: 10;
  box-shadow: -18px 0 40px rgba(0, 0, 0, 0.45);
}

.close {
  position: absolute;
  top: 14px;
  right: 16px;
  background: transparent;
  border: none;
  color: var(--ink-dim);
  font-size: 26px;
  line-height: 1;
  cursor: pointer;
}

.close:hover { color: var(--ink); }

.detail h2 { font-size: 21px; margin-bottom: 4px; }

.detail .sub { color: var(--ink-dim); margin: 0 0 18px; font-size: 13px; }

.stat-row { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 18px; }

.stat {
  background: var(--panel-2);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px 12px;
}

.stat span { display: block; color: var(--ink-faint); font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; }

.stat strong { font-size: 17px; font-weight: 620; }

.detail h3 { font-size: 13px; text-transform: uppercase; letter-spacing: 0.07em; color: var(--ink-faint); margin: 22px 0 10px; }

.steps { list-style: none; margin: 0; padding: 0; counter-reset: step; }

.steps li {
  counter-increment: step;
  position: relative;
  padding: 0 0 14px 34px;
  color: var(--ink-dim);
  font-size: 13px;
}

.steps li::before {
  content: counter(step);
  position: absolute;
  left: 0;
  top: 0;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 1px solid var(--accent-dim);
  color: var(--accent);
  font-size: 11.5px;
  display: grid;
  place-items: center;
}

.steps b { color: var(--ink); font-weight: 600; }

.chains { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 6px; }

/* The model page: how the board was fitted, and how it did out of sample. */
.two-col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
  align-items: start;
}

table.compact th,
table.compact td {
  padding: 7px 10px;
  font-size: 13px;
}

table.compact tr.chosen td {
  color: var(--accent);
  background: rgba(79, 209, 197, 0.08);
}

table.compact tr.chosen td:first-child {
  font-weight: 600;
}

.formula {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  color: var(--gold);
  background: var(--panel-2);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px 14px;
  margin: 14px 0 18px;
  font-size: 14px;
  display: inline-block;
}

.obligations {
  display: flex;
  gap: 18px;
  flex-wrap: wrap;
}
